components.css:
.ds-button-primary { display: inline-flex; align-items: center; justify-content: center; box-sizing: border-box; height: 2.25rem; padding: 0 0.75rem; border: 1px solid transparent; border-radius: var(--radius, 0.75rem); background-clip: padding-box; font-size: 0.875rem; line-height: 1.25rem; font-weight: 500; font-family: var(--font-geist-sans, Geist, sans-serif); white-space: nowrap; color: var(--foreground, #17272d); background: transparent; cursor: pointer; user-select: none; transition: all 150ms cubic-bezier(0.4, 0, 0.2, 1); }
.ds-button-primary:focus-visible { outline: none; border-color: var(--ring, #0f5961); box-shadow: 0 0 0 3px color-mix(in oklab, var(--ring, #0f5961) 30%, transparent); }
.ds-button-primary:active:not([aria-haspopup]) { transform: translateY(1px); }
.ds-button-primary:disabled { pointer-events: none; opacity: 0.5; }
.ds-button-primary { background: var(--primary, #0f5961); color: var(--primary-foreground, #ffffff); }
.ds-button-primary:hover { background: color-mix(in oklab, var(--primary, #0f5961) 80%, transparent); }

.ds-button-secondary { display: inline-flex; align-items: center; justify-content: center; box-sizing: border-box; height: 2.25rem; padding: 0 0.75rem; border: 1px solid transparent; border-radius: var(--radius, 0.75rem); background-clip: padding-box; font-size: 0.875rem; line-height: 1.25rem; font-weight: 500; font-family: var(--font-geist-sans, Geist, sans-serif); white-space: nowrap; color: var(--foreground, #17272d); background: transparent; cursor: pointer; user-select: none; transition: all 150ms cubic-bezier(0.4, 0, 0.2, 1); }
.ds-button-secondary:focus-visible { outline: none; border-color: var(--ring, #0f5961); box-shadow: 0 0 0 3px color-mix(in oklab, var(--ring, #0f5961) 30%, transparent); }
.ds-button-secondary:active:not([aria-haspopup]) { transform: translateY(1px); }
.ds-button-secondary:disabled { pointer-events: none; opacity: 0.5; }
.ds-button-secondary { background: var(--secondary, #e7eeea); color: var(--secondary-foreground, #214044); }
.ds-button-secondary:hover { background: color-mix(in oklch, var(--secondary, #e7eeea), var(--foreground, #17272d) 5%); }

.ds-button-outline { display: inline-flex; align-items: center; justify-content: center; box-sizing: border-box; height: 2.25rem; padding: 0 0.75rem; border: 1px solid transparent; border-radius: var(--radius, 0.75rem); background-clip: padding-box; font-size: 0.875rem; line-height: 1.25rem; font-weight: 500; font-family: var(--font-geist-sans, Geist, sans-serif); white-space: nowrap; color: var(--foreground, #17272d); background: transparent; cursor: pointer; user-select: none; transition: all 150ms cubic-bezier(0.4, 0, 0.2, 1); }
.ds-button-outline:focus-visible { outline: none; border-color: var(--ring, #0f5961); box-shadow: 0 0 0 3px color-mix(in oklab, var(--ring, #0f5961) 30%, transparent); }
.ds-button-outline:active:not([aria-haspopup]) { transform: translateY(1px); }
.ds-button-outline:disabled { pointer-events: none; opacity: 0.5; }
.ds-button-outline { background: var(--card, #ffffff); border-color: var(--field-border, #758b84); }
.ds-button-outline:hover { background: var(--muted, #edf0eb); }
:host-context(.dark) .ds-button-outline { background: transparent; }
:host-context(.dark) .ds-button-outline:hover { background: color-mix(in oklab, var(--input, #e4ece8) 30%, transparent); }
.ds-button-outline:focus-visible { border-color: var(--ring, #0f5961); }

.ds-button-ghost { display: inline-flex; align-items: center; justify-content: center; box-sizing: border-box; height: 2.25rem; padding: 0 0.75rem; border: 1px solid transparent; border-radius: var(--radius, 0.75rem); background-clip: padding-box; font-size: 0.875rem; line-height: 1.25rem; font-weight: 500; font-family: var(--font-geist-sans, Geist, sans-serif); white-space: nowrap; color: var(--foreground, #17272d); background: transparent; cursor: pointer; user-select: none; transition: all 150ms cubic-bezier(0.4, 0, 0.2, 1); }
.ds-button-ghost:focus-visible { outline: none; border-color: var(--ring, #0f5961); box-shadow: 0 0 0 3px color-mix(in oklab, var(--ring, #0f5961) 30%, transparent); }
.ds-button-ghost:active:not([aria-haspopup]) { transform: translateY(1px); }
.ds-button-ghost:disabled { pointer-events: none; opacity: 0.5; }
.ds-button-ghost:hover { background: var(--muted, #edf0eb); }
:host-context(.dark) .ds-button-ghost:hover { background: color-mix(in oklab, var(--muted, #edf0eb) 50%, transparent); }

.ds-button-destructive { display: inline-flex; align-items: center; justify-content: center; box-sizing: border-box; height: 2.25rem; padding: 0 0.75rem; border: 1px solid transparent; border-radius: var(--radius, 0.75rem); background-clip: padding-box; font-size: 0.875rem; line-height: 1.25rem; font-weight: 500; font-family: var(--font-geist-sans, Geist, sans-serif); white-space: nowrap; color: var(--foreground, #17272d); background: transparent; cursor: pointer; user-select: none; transition: all 150ms cubic-bezier(0.4, 0, 0.2, 1); }
.ds-button-destructive:focus-visible { outline: none; border-color: var(--ring, #0f5961); box-shadow: 0 0 0 3px color-mix(in oklab, var(--ring, #0f5961) 30%, transparent); }
.ds-button-destructive:active:not([aria-haspopup]) { transform: translateY(1px); }
.ds-button-destructive:disabled { pointer-events: none; opacity: 0.5; }
.ds-button-destructive { background: color-mix(in oklab, var(--destructive, #b63132) 10%, transparent); color: var(--destructive, #b63132); }
.ds-button-destructive:hover { background: color-mix(in oklab, var(--destructive, #b63132) 20%, transparent); }
.ds-button-destructive:focus-visible { border-color: color-mix(in oklab, var(--destructive, #b63132) 40%, transparent); box-shadow: 0 0 0 3px color-mix(in oklab, var(--destructive, #b63132) 20%, transparent); }
:host-context(.dark) .ds-button-destructive { background: color-mix(in oklab, var(--destructive, #b63132) 20%, transparent); }
:host-context(.dark) .ds-button-destructive:hover { background: color-mix(in oklab, var(--destructive, #b63132) 30%, transparent); }
:host-context(.dark) .ds-button-destructive:focus-visible { box-shadow: 0 0 0 3px color-mix(in oklab, var(--destructive, #b63132) 40%, transparent); }

.ds-button-link { display: inline-flex; align-items: center; justify-content: center; box-sizing: border-box; height: 2.25rem; padding: 0 0.75rem; border: 1px solid transparent; border-radius: var(--radius, 0.75rem); background-clip: padding-box; font-size: 0.875rem; line-height: 1.25rem; font-weight: 500; font-family: var(--font-geist-sans, Geist, sans-serif); white-space: nowrap; color: var(--foreground, #17272d); background: transparent; cursor: pointer; user-select: none; transition: all 150ms cubic-bezier(0.4, 0, 0.2, 1); }
.ds-button-link:focus-visible { outline: none; border-color: var(--ring, #0f5961); box-shadow: 0 0 0 3px color-mix(in oklab, var(--ring, #0f5961) 30%, transparent); }
.ds-button-link:active:not([aria-haspopup]) { transform: translateY(1px); }
.ds-button-link:disabled { pointer-events: none; opacity: 0.5; }
.ds-button-link { color: var(--primary, #0f5961); text-underline-offset: 4px; }
.ds-button-link:hover { text-decoration-line: underline; }

.ds-field { display: grid; gap: 0.75rem; }
.ds-field-label { font: 500 0.875rem/1 var(--font-noto-sans, "Noto Sans", sans-serif); color: var(--foreground, #17272d); }
.ds-input { display: block; width: 100%; min-width: 0; box-sizing: border-box; height: 2.25rem; padding: 0.25rem 0.75rem; border: 1px solid var(--field-border, #758b84); border-radius: var(--radius, 0.75rem); background: var(--card, #ffffff); color: var(--foreground, #17272d); font: 1rem/1.5 var(--font-noto-sans, "Noto Sans", sans-serif); outline: none; transition: color 150ms cubic-bezier(0.4, 0, 0.2, 1), box-shadow 150ms cubic-bezier(0.4, 0, 0.2, 1), background-color 150ms cubic-bezier(0.4, 0, 0.2, 1); }
.ds-input::placeholder { color: var(--muted-foreground, #54696a); }
.ds-input:focus-visible { border-color: var(--ring, #0f5961); box-shadow: 0 0 0 3px color-mix(in oklab, var(--ring, #0f5961) 30%, transparent); }
.ds-input[aria-invalid="true"] { border-color: var(--destructive, #b63132); box-shadow: 0 0 0 3px color-mix(in oklab, var(--destructive, #b63132) 20%, transparent); }
:host-context(.dark) .ds-input[aria-invalid="true"] { border-color: color-mix(in oklab, var(--destructive, #b63132) 50%, transparent); box-shadow: 0 0 0 3px color-mix(in oklab, var(--destructive, #b63132) 40%, transparent); }
.ds-input:disabled { pointer-events: none; opacity: 0.5; }
@media (min-width: 48rem) { .ds-input { font-size: 0.875rem; line-height: 1.25rem; } }

.ds-card { display: flex; flex-direction: column; overflow: hidden; border: 1px solid var(--border, #cbd8d1); border-radius: calc(var(--radius, 0.75rem) * 1.8); background-color: var(--card, #ffffff); color: var(--foreground, #17272d); font: 0.875rem/1.25rem var(--font-noto-sans, "Noto Sans", sans-serif); box-shadow: var(--shadow-sm, 0 1px 3px 0 rgb(0 0 0 / 0.1), 0 1px 2px -1px rgb(0 0 0 / 0.1)); gap: 1.5rem; padding: 1.5rem; }
.ds-card-header { display: grid; gap: 0.375rem; }
.ds-card-title { margin: 0; font: 600 1.25rem/1.75rem var(--font-geist-sans, Geist, sans-serif); letter-spacing: -0.025em; }
.ds-card-description { margin: 0; color: var(--muted-foreground, #54696a); }

.ds-hero { display: flex; flex-direction: column; overflow: hidden; border: 1px solid var(--border, #cbd8d1); border-radius: calc(var(--radius, 0.75rem) * 1.8); background-color: var(--card, #ffffff); color: var(--foreground, #17272d); font: 0.875rem/1.25rem var(--font-noto-sans, "Noto Sans", sans-serif); box-shadow: var(--shadow-sm, 0 1px 3px 0 rgb(0 0 0 / 0.1), 0 1px 2px -1px rgb(0 0 0 / 0.1)); gap: 2rem; padding: 2rem; border-color: color-mix(in oklab, var(--primary, #0f5961) 20%, transparent); background-color: var(--primary-soft, #dceae6); background-image: radial-gradient(circle at 88% 18%, color-mix(in srgb, var(--highlight, #d99a32) 20%, transparent), transparent 32%), linear-gradient(to right, color-mix(in srgb, var(--primary, #0f5961) 8%, transparent) 1px, transparent 1px), linear-gradient(to bottom, color-mix(in srgb, var(--primary, #0f5961) 8%, transparent) 1px, transparent 1px); background-size: auto, 3.25rem 3.25rem, 3.25rem 3.25rem; }
.ds-hero-header { display: grid; gap: 1rem; max-width: 48rem; }
.ds-hero-eyebrow { margin: 0; display: inline-flex; align-items: center; gap: 0.5rem; font: 600 0.875rem/1.25rem var(--font-geist-sans, Geist, sans-serif); letter-spacing: 0.16em; text-transform: uppercase; color: var(--primary, #0f5961); }
.ds-hero-eyebrow::before { content: ""; width: 0.5rem; height: 0.5rem; flex-shrink: 0; border-radius: calc(var(--radius, 0.75rem) * 0.6); background: var(--highlight, #d99a32); }
.ds-hero-title { margin: 0; font: 600 2.25rem/2.5rem var(--font-geist-sans, Geist, sans-serif); letter-spacing: -0.025em; text-wrap: balance; }
@media (min-width: 40rem) { .ds-hero { gap: 3rem; padding: 3rem; } .ds-hero-title { font-size: 3.75rem; line-height: 1; } }

.ds-section-label { margin: 0 0 1rem; font: 600 0.875rem/1.25rem var(--font-geist-sans, Geist, sans-serif); color: var(--muted-foreground, #54696a); }
.ds-section-links { display: flex; flex-wrap: wrap; gap: 0.5rem; margin: 0; padding: 0; list-style: none; }
.ds-section-links > li { max-width: 100%; }
.ds-section-link { display: inline-flex; align-items: center; justify-content: center; box-sizing: border-box; min-height: 2.25rem; padding: 0.25rem 0.75rem; border: 1px solid transparent; border-radius: var(--radius, 0.75rem); background-clip: padding-box; font-size: 0.875rem; line-height: 1.25rem; font-weight: 500; font-family: var(--font-geist-sans, Geist, sans-serif); white-space: normal; overflow-wrap: anywhere; text-align: left; color: var(--foreground, #17272d); background: transparent; cursor: pointer; user-select: none; transition: all 150ms cubic-bezier(0.4, 0, 0.2, 1); }
.ds-section-link:focus-visible { outline: none; border-color: var(--ring, #0f5961); box-shadow: 0 0 0 3px color-mix(in oklab, var(--ring, #0f5961) 30%, transparent); }
.ds-section-link:active:not([aria-haspopup]) { transform: translateY(1px); }
.ds-section-link:disabled { pointer-events: none; opacity: 0.5; }
.ds-section-link { width: 100%; justify-content: flex-start; text-decoration: none; }
.ds-section-link:hover { background: var(--muted, #edf0eb); }
:host-context(.dark) .ds-section-link:hover { background: color-mix(in oklab, var(--muted, #edf0eb) 50%, transparent); }
.ds-section-link[aria-current="page"] { background: var(--secondary, #e7eeea); color: var(--secondary-foreground, #214044); text-decoration-line: underline; text-decoration-thickness: 2px; text-underline-offset: 4px; }
.ds-section-link[aria-current="page"]:hover { background: color-mix(in oklch, var(--secondary, #e7eeea), var(--foreground, #17272d) 5%); }
@media (min-width: 64rem) { .ds-section-links { flex-direction: column; } }
